#include "lumafem/analysis.hpp"
#include <cmath>
#include <functional>
#include <iostream>
#include <limits>
#include <string>
using namespace lumafem;
namespace {
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
void close(double a,double b,double abs,double rel,const char* s){check(std::isfinite(a)&&std::abs(a-b)<=abs+rel*std::abs(b),s);}
MaterialParameters concrete(){MaterialParameters p;p.id="c";p.fc=30;p.e0=.002;p.fr=6;p.ft=3;p.Gft=.1;p.Gcp=10;p.unloadRatio=.1;p.referenceLength=100;p.crushReferenceStrain=.0035;p.lchT=10;p.lchC=10;return p;}
MaterialParameters steel(){MaterialParameters p;p.id="s";p.kind=MaterialKind::SteelBilinear;p.E=200000;p.fy=400;p.b=.01;return p;}
ModelDefinition beam(){ModelDefinition d;d.identity={"test-project","revision","snapshot","run",""};d.name="independent elastic benchmark";d.geometry={1000,20,40,0};MaterialParameters e;e.id="elastic";e.kind=MaterialKind::Elastic;e.E=30000;d.materials={e};d.concreteMaterialId=e.id;d.reinforcement.mode="direct";d.supports={{"left",0,{true,true,false},{0,0,0}},{"right",1000,{false,true,false},{0,0,0}}};d.loads={{"jack1",300,{0,-50,0}},{"jack2",700,{0,-50,0}}};d.controlX=500;d.discretization={"custom",100,3,40,"gauss_weight_v1"};d.observations.referencePhase="S0";d.analysis.initialStep=.02;d.analysis.maximumStep=.02;d.analysis.maximumControlDisplacement=.06;return d;}
void concrete_anchors_tangent(){auto p=concrete();MaterialState s;auto a=evaluateMaterial(p,s,-p.e0);check(a.ok,"peak valid");close(a.stress,-30,1e-6,1e-6,"compression peak");auto t=evaluateMaterial(p,s,p.ft/(2*p.fc/p.e0));check(t.ok,"crack valid");close(t.stress,3,1e-6,1e-6,"tensile peak");for(double e:{-.0007,-.003,.0002}){auto mid=evaluateMaterial(p,s,e);check(mid.ok,"interior valid");for(double h:{1e-8,3e-9,1e-9}){auto l=evaluateMaterial(p,s,e-h),r=evaluateMaterial(p,s,e+h);check(l.ok&&r.ok,"difference candidates valid");close((r.stress-l.stress)/(2*h),mid.tangent,3,1e-4,"material tangent independently differenced");}}}
void concrete_energy(){auto p=concrete();double E=2*p.fc/p.e0;double end=2*p.Gft/(p.lchT*p.ft);double lastw=0,lasts=p.ft,energy=0;for(int i=1;i<=20000;++i){double e=p.ft/E+(end-p.ft/E)*i/20000.;auto r=evaluateMaterial(p,{},e);check(r.ok,"tension integration");double w=p.lchT*(e-r.stress/E);energy+=(lasts+r.stress)*.5*(w-lastw);lastw=w;lasts=r.stress;}close(energy,p.Gft,1e-8,1e-3,"independent tensile opening integral");double du=2*p.Gcp/(p.fc+p.fr),eu=p.e0+du/p.lchC-(p.fc-p.fr)/E;double delta=0,q=p.fc;energy=0;for(int i=1;i<=20000;++i){double e=p.e0+(eu-p.e0)*i/20000.;auto r=evaluateMaterial(p,{},-e);check(r.ok,"compression integration");double next=p.lchC*(e-p.e0-(-r.stress-p.fc)/E);energy+=(q-r.stress)*.5*(next-delta);delta=next;q=-r.stress;}close(energy,p.Gcp,1e-7,1e-3,"independent q-delta integral");}
void steel_history(){auto p=steel();auto r=evaluateMaterial(p,{},.004);check(r.ok&&r.state.yielded,"steel yields");close(r.stress,404,1e-6,1e-6,"bilinear stress");close(r.tangent,2000,1e-6,1e-6,"postyield tangent");auto reverse=evaluateMaterial(p,r.state,.0035);close(reverse.tangent,200000,1e-6,1e-6,"elastic unloading");auto noise=evaluateMaterial(p,r.state,-.02);(void)noise;auto repeat=evaluateMaterial(p,r.state,.0035);close(repeat.stress,reverse.stress,1e-9,1e-9,"trial does not pollute committed state");check(r.state.strain==.004,"anchor unchanged");}
void concrete_history_domains(){auto p=concrete();auto a=evaluateMaterial(p,{},-.003);check(a.ok,"compression history");auto r=evaluateMaterial(p,a.state,-.0025);check(r.ok,"unload valid");check(std::isnan(r.state.referenceCompressionStrain),"unloaded reference unavailable");close(r.state.maxReferenceCompressionStrain,a.state.maxReferenceCompressionStrain,1e-12,1e-12,"historical max preserved");auto noise=evaluateMaterial(p,a.state,.02);(void)noise;auto again=evaluateMaterial(p,a.state,-.0025);close(again.stress,r.stress,1e-9,1e-9,"concrete rollback isolation");p.lchT=1e6;check(!evaluateMaterial(p,{},.001).ok,"invalid mapped length rejected");p=concrete();p.crushReferenceStrain=.1;check(!evaluateMaterial(p,{},-.003).ok,"invalid reference criterion rejected");}
void preparation_geometry(){auto d=beam();auto p=prepareModel(d);check(p.ok,"elastic preparation");check(p.model.nodes.size()==11&&p.model.elements.size()==10&&p.model.sections.size()==30,"mesh count");double length=0;for(auto&s:p.model.sections)length+=s.integrationLength;close(length,1000,1e-10,1e-10,"Gauss physical integration lengths");auto bad=d;bad.supports.clear();check(!prepareModel(bad).ok,"rigid body rejected");bad=d;bad.geometry.width=-1;check(!prepareModel(bad).ok,"negative geometry rejected");}
void section_stiffness(){auto p=prepareModel(beam());check(p.ok,"section fixture");auto sec=p.model.sections[0];double EA=0,EAy=0,EI=0;for(auto&f:sec.fibers){EA+=f.area*f.material.E;EAy-=f.area*f.material.E*f.eta;EI+=f.area*f.material.E*f.eta*f.eta;}auto r=evaluateSection(sec,{},.0001,.00001);check(r.ok,"section integration");close(r.N,EA*.0001+EAy*.00001,1e-6,1e-6,"section independent axial sum");close(r.M,EAy*.0001+EI*.00001,1e-6,1e-6,"section independent bending sum");close(r.tangent[3],EI,1e-6,1e-6,"section EI");auto changed=sec;changed.edges.clear();auto noedge=evaluateSection(changed,{},.0001,.00001);close(noedge.M,r.M,1e-8,1e-8,"edge no stiffness");}
void general_sparse_solve(){Eigen::SparseMatrix<double>A(2,2);A.insert(0,0)=0;A.insert(0,1)=2;A.insert(1,0)=3;A.insert(1,1)=-1;Eigen::VectorXd b(2);b<<4,4;auto x=solveScaledSystem(A,b,{10,100},{.1,2},1e-10);check(x.ok,"general nonsymmetric indefinite solve");close(x.solution[0],2,1e-10,1e-10,"general solve x");close(x.solution[1],2,1e-10,1e-10,"general solve y");}
void elastic_analysis(){auto d=beam();auto p=prepareModel(d);check(p.ok,"analysis fixture");std::vector<AcceptedStep>steps;AnalysisHooks h;h.persist=[&](const AcceptedStep&s){steps.push_back(s);PersistedStepReceipt r;r.ok=true;r.identity=s.identity;r.persistedSequence=(long long)s.sequence;r.transactionId="unit-memory-port";return r;};auto sum=runAnalysis(p.model,p.model.definition.analysis,h);check(sum.termination==Termination::SafetyLimit,"elastic end is safety not crushing");check(steps.size()>1,"actual accepted loading");double EI=30000.*20*40*40*40/12*(1-1./1600);double compliance=300.*(3*1000.*1000-4*300.*300)/(48*EI);for(auto&s:steps){if(s.phase!=Phase::J)continue;close(s.controlDisplacement,s.P*compliance,1e-8,1e-5,"two-point analytical deflection");close(s.P1,s.P/2,1e-6,1e-6,"two jack total");close(s.reactions[1],s.P/2,1e-5,1e-6,"left reaction");close(s.reactions[s.reactions.size()-2],s.P/2,1e-5,1e-6,"right reaction");check(s.convergence.residualPassed&&s.convergence.correctionPassed&&s.convergence.controlPassed,"joint convergence");}check(!sum.physicalCriterionReached,"safety never physical crushing");}
}
int main(){int failed=0;for(auto test:std::initializer_list<std::pair<const char*,std::function<void()>>>{{"concrete_anchors_tangent",concrete_anchors_tangent},{"concrete_energy",concrete_energy},{"steel_history",steel_history},{"concrete_history_domains",concrete_history_domains},{"preparation_geometry",preparation_geometry},{"section_stiffness",section_stiffness},{"general_sparse_solve",general_sparse_solve},{"elastic_analysis",elastic_analysis}}){try{test.second();std::cout<<"PASS "<<test.first<<'\n';}catch(const std::exception&e){++failed;std::cerr<<"FAIL "<<test.first<<": "<<e.what()<<'\n';}}return failed?1:0;}

